  insert into public.course_items (course_id, kind, position, title, content) select cid, 'topic', 5, $j$2.1 Music in the Old Testament$j$, $j${"readings": [{"title": "Exodus 15 (King James Version)", "url": "/portal/bible/Exodus/15"}], "body": "Music appears in the Bible from the earliest pages. Genesis 4:21 names Jubal as the father of all such as handle the harp and organ. After God delivered Israel through the Red Sea, Moses and the children of Israel sang. Exodus 15:1 says, Then sang Moses and the children of Israel this song unto the LORD, and spake, saying, I will sing unto the LORD, for he hath triumphed gloriously. Miriam the prophetess led the women with timbrels and dancing in Exodus 15:20. Deborah and Barak sang a song of victory in Judges 5.\n\nMusic had a place in the life of the nation. People sang at celebrations, at times of victory and in times of sorrow. In Psalm 137 the exiles in Babylon hanged their harps upon the willows because they could not sing the songs of Zion in a strange land. David played the harp to calm King Saul in First Samuel 16:23. Singing was also a way to remember God's works and to teach children His law.\n\nUnder David and Solomon, music became part of the temple worship. First Chronicles 25 describes families of Levites trained as singers and musicians, and verse 7 says that they were instructed in the songs of the LORD, and numbered two hundred fourscore and eight, which is 288. Second Chronicles 5:13 says that the trumpeters and singers were as one, to make one sound to be heard in praising and thanking the LORD, and the house was filled with a cloud. Unity and skill were part of worship. In Second Chronicles 20:21, King Jehoshaphat appointed singers to go out before the army and praise the LORD.\n\nNotice that Old Testament music was sung to God, taught carefully, and tied to His works. It was offered by people trained for the task.\n\nYour task: (1) Name three Old Testament songs or singers and the occasion for each. (2) Describe how music was organized in the temple under David. (3) Explain what Second Chronicles 5:13 teaches about unity in worship.\n\nFlorida standards: MU.912.H.1, MU.912.C.1.", "video": "", "presenter": "Dr. Alex L. Jenkins Sr.", "standards": "MU.912.H.1, MU.912.C.1", "script": "Welcome back. Listen, music is not a modern invention. It is woven through the Old Testament from the beginning.\n\nGenesis 4:21 names Jubal as the father of all such as handle the harp and organ. After God opened the Red Sea, Moses and Israel sang. Exodus 15:1 says, I will sing unto the LORD, for he hath triumphed gloriously. Miriam took a timbrel and led the women. Deborah and Barak sang a victory song in Judges 5.\n\nNow watch this. David played the harp, and Saul was refreshed. In Psalm 137, the exiles hanged their harps on the willows because grief was too heavy for song. So music carries joy and it carries sorrow.\n\nLook at the temple. First Chronicles 25 tells us that families of Levites were trained as singers and musicians, two hundred eighty eight of them, instructed in the songs of the LORD. This was skilled, organized work.\n\nSecond Chronicles 5:13 says the trumpeters and singers were as one, to make one sound in praising and thanking the LORD, and the house was filled with a cloud. Unity matters. And in Second Chronicles 20:21, Jehoshaphat sent the singers out before the army.\n\nYour task is to name three Old Testament songs, describe the temple musicians and explain Second Chronicles 5:13. Take the four question check. Excellence, Faith, Purpose. I will see you in the next lesson."}$j$::jsonb where not exists (select 1 from public.course_items where course_id = cid and kind = 'topic' and title = $j$2.1 Music in the Old Testament$j$);
  insert into public.course_items (course_id, kind, position, title, content) select cid, 'topic', 6, $j$2.2 The Psalms as Songs$j$, $j${"readings": [{"title": "Psalm 100 (King James Version)", "url": "/portal/bible/Psalms/100"}], "body": "The Book of Psalms is Israel's songbook. The name comes from a Greek word for songs sung with stringed instruments. Psalms were written over many centuries. Many are by David, and others by Asaph, the sons of Korah, Solomon and Moses. There are 150 psalms, and Psalm 119 is the longest chapter in the Bible.\n\nMany psalms have notes in their titles that may be directions for the musicians. Some titles name an instrument, such as Neginoth, which may refer to stringed instruments. The word Selah appears in many psalms and may mark a pause to think or a musical interlude. Scholars are not sure of the exact meaning, so we should say that plainly and not guess.\n\nThe psalms use a feature called parallelism, in which a second line repeats, contrasts or builds on the first. Psalm 100:1 and 2 says, Make a joyful noise unto the LORD, all ye lands. Serve the LORD with gladness: come before his presence with singing. The psalms include praise, thanksgiving, lament, trust, repentance and royal psalms. Psalm 98:1 says, O sing unto the LORD a new song; for he hath done marvellous things. Psalm 96:1 says, O sing unto the LORD a new song: sing unto the LORD, all the earth. A new song is fresh worship that comes from a heart touched by God.\n\nPsalm 150 closes the book with a call for everything that has breath to praise the LORD, with trumpet, harp, timbrel, strings, organs and cymbals. Psalm 47:7 says, For God is the King of all the earth: sing ye praises with understanding. Understanding means we think about what we sing.\n\nMany hymns and choruses have been based on the psalms. Singing a psalm slowly, line by line, can be a good way to pray.\n\nYour task: (1) Explain what the Book of Psalms is and what it contains. (2) Tell what parallelism is and give an example. (3) Explain Psalm 47:7 and why singing with understanding matters.\n\nFlorida standards: MU.912.H.1, MU.912.C.1.", "video": "", "presenter": "Dr. Alex L. Jenkins Sr.", "standards": "MU.912.H.1, MU.912.C.1", "script": "Welcome back. Listen, the Bible has its own songbook, and it is the Book of Psalms.\n\nThe name comes from a word for songs sung with stringed instruments. There are 150 psalms, written over many centuries by David, Asaph, the sons of Korah, Solomon, Moses and others. Some titles contain notes for the musicians. The word Selah may mark a pause or an interlude, but scholars are not certain, so we say so honestly.\n\nNow watch this. The psalms use parallelism. The second line repeats, contrasts or builds on the first. Psalm 100:1 and 2. Make a joyful noise unto the LORD, all ye lands. Serve the LORD with gladness: come before his presence with singing.\n\nLook at the kinds of psalms. There are psalms of praise, thanksgiving, lament, trust and repentance. Psalm 98:1 says, O sing unto the LORD a new song; for he hath done marvellous things. A new song is fresh worship from a heart touched by God.\n\nPsalm 150 closes the book with a call for everything that has breath to praise the LORD. And Psalm 47:7 says, sing ye praises with understanding. Think about what you sing.\n\nMany hymns are based on the psalms. Try singing a psalm slowly, line by line, as a prayer.\n\nYour task is to explain the Book of Psalms, give an example of parallelism and explain singing with understanding. Take the four question check. Excellence, Faith, Purpose. I will see you in the next lesson."}$j$::jsonb where not exists (select 1 from public.course_items where course_id = cid and kind = 'topic' and title = $j$2.2 The Psalms as Songs$j$);
  insert into public.course_items (course_id, kind, position, title, content) select cid, 'topic', 7, $j$2.3 Music in the New Testament and the Early Church$j$, $j${"readings": [{"title": "Acts 16 (King James Version)", "url": "/portal/bible/Acts/16"}], "body": "Music continues in the New Testament. When Mary learned she would bear the Savior, she lifted a song of praise. Luke 1:46 and 47 says, My soul doth magnify the Lord, And my spirit hath rejoiced in God my Saviour. At the Last Supper, Jesus and His disciples ended the evening with a hymn. Matthew 26:30 says, And when they had sung an hymn, they went out into the mount of Olives. Most likely this was a part of the Hallel psalms, Psalm 113 to 118, which Jews sang at Passover.\n\nIn Acts 16:25, Paul and Silas were in prison in Philippi, and at midnight they prayed and sang praises unto God, and the prisoners heard them. Song strengthened them and became a witness. The apostle Paul gave direction to the churches. Ephesians 5:19 says, Speaking to yourselves in psalms and hymns and spiritual songs, singing and making melody in your heart to the Lord. Colossians 3:16 says, Let the word of Christ dwell in you richly in all wisdom; teaching and admonishing one another in psalms and hymns and spiritual songs, singing with grace in your hearts to the Lord. Singing is both worship toward God and teaching toward one another.\n\nFirst Corinthians 14:15 says, I will sing with the spirit, and I will sing with the understanding also. Verse 40 adds, Let all things be done decently and in order. Worship should come from the heart and the mind, and be orderly and clear so all are built up. Revelation 5:9 shows heaven singing a new song to the Lamb who was slain.\n\nThe early church sang without large instruments. Early Christians sang psalms, hymns and short confessions. Over time, chant developed as a way for congregations and choirs to sing Scripture, and it grew into the music of the medieval church.\n\nYour task: (1) Name three New Testament examples of singing. (2) Explain what Ephesians 5:19 and Colossians 3:16 teach about singing. (3) Explain First Corinthians 14:15 and 14:40.\n\nFlorida standards: MU.912.H.1, MU.912.C.3.", "video": "", "presenter": "Dr. Alex L. Jenkins Sr.", "standards": "MU.912.H.1, MU.912.C.3", "script": "Welcome back. Listen, the church was born singing.\n\nMary sang when she heard she would bear the Savior. Luke 1:46 and 47. My soul doth magnify the Lord, And my spirit hath rejoiced in God my Saviour. At the Last Supper, Jesus and His disciples ended with a hymn. Matthew 26:30. It was most likely from the Hallel psalms sung at Passover.\n\nNow watch this. Paul and Silas were in prison in Philippi. At midnight they prayed and sang praises to God, and the prisoners heard them. Song strengthened them and became a witness. Acts 16:25.\n\nLook at Paul's teaching. Ephesians 5:19, speaking to yourselves in psalms and hymns and spiritual songs, singing and making melody in your heart to the Lord. Colossians 3:16, teaching and admonishing one another in psalms and hymns and spiritual songs. So singing is worship toward God and teaching toward one another.\n\nFirst Corinthians 14:15. I will sing with the spirit, and I will sing with the understanding also. And verse 40, Let all things be done decently and in order. Worship comes from the heart and the mind, and it should be clear so that all are built up. In Revelation 5:9, heaven sings a new song to the Lamb.\n\nThe early church sang psalms, hymns and short confessions, and over time chant developed to carry Scripture.\n\nYour task is to name three New Testament examples of singing, explain Ephesians 5:19 and Colossians 3:16, and explain First Corinthians 14. Take the four question check. Excellence, Faith, Purpose. I will see you in the next lesson."}$j$::jsonb where not exists (select 1 from public.course_items where course_id = cid and kind = 'topic' and title = $j$2.3 Music in the New Testament and the Early Church$j$);
  insert into public.course_items (course_id, kind, position, title, content) select cid, 'topic', 8, $j$2.4 The Purpose of Worship Music$j$, $j${"readings": [{"title": "John 4 (King James Version)", "url": "/portal/bible/John/4"}], "body": "Why do we sing in church? The Bible gives several reasons. First, we sing to praise God. Psalm 100:2 says to come before his presence with singing. Second, we sing to give thanks. Psalm 95:2 says, Let us come before his presence with thanksgiving, and make a joyful noise unto him with psalms. Third, we sing to teach and remember truth. Colossians 3:16 says to teach and admonish one another in song. Fourth, we sing to encourage each other and to unite as one body. Fifth, we sing to testify to those who hear, as Paul and Silas did in prison.\n\nWorship music should be centered on God and not on the performer. It should be true to Scripture, since we teach doctrine in song. It should be understandable, so the people can sing with understanding. It should be done with skill, since Psalm 33:3 says to play skilfully, and with order, since First Corinthians 14:40 says all things should be decent and in order. It should come from a sincere heart. Jesus said in John 4:24 that God is a Spirit: and they that worship him must worship him in spirit and in truth.\n\nCongregations and churches use different styles. Some sing hymns with organ and piano, some sing gospel with choir and band, some sing contemporary songs, and some sing a cappella, which means voices without instruments. A church may choose different instruments and styles for sound reasons of culture and ministry. The test is not the style alone but whether the words are true, the heart is sincere and the whole is done to the glory of God. Believers can disagree kindly about style without dividing over it.\n\nMusic alone is not worship. Worship is a life of obedience, with song as one expression.\n\nYour task: (1) List four purposes of singing in church. (2) List five marks of good worship music. (3) Explain why believers should discuss style with kindness.\n\nFlorida standards: MU.912.C.3, MU.912.H.1.", "video": "", "presenter": "Dr. Alex L. Jenkins Sr.", "standards": "MU.912.C.3, MU.912.H.1", "script": "Welcome back. Listen, why do we sing in church? Let the Word answer.\n\nWe sing to praise God. Psalm 100:2, come before his presence with singing. We sing to give thanks. Psalm 95:2. We sing to teach and remember truth. Colossians 3:16. We sing to encourage one another and be united as one body. And we sing to testify to those who hear.\n\nNow watch this. Good worship music is centered on God, not on the performer. It is true to Scripture because we teach doctrine in song. It is understandable. It is done with skill, because Psalm 33:3 says play skilfully. It is orderly, because First Corinthians 14:40 says decently and in order. And it comes from a sincere heart. John 4:24. God is a Spirit: and they that worship him must worship him in spirit and in truth.\n\nLook at style. Some churches sing hymns with organ and piano. Some sing gospel with choir and band. Some sing contemporary songs. Some sing a cappella, which means voices without instruments. The test is not style alone. Are the words true, is the heart sincere, and is it all done to the glory of God? Believers can disagree kindly about style without dividing.\n\nRemember, music alone is not worship. Worship is a life of obedience, and song is one expression of it.\n\nYour task is to list four purposes of church singing, five marks of good worship music, and explain how to discuss style with kindness. Take the four question check. Excellence, Faith, Purpose. I will see you in the next lesson."}$j$::jsonb where not exists (select 1 from public.course_items where course_id = cid and kind = 'topic' and title = $j$2.4 The Purpose of Worship Music$j$);
  insert into public.course_items (course_id, kind, position, title, content) select cid, 'assessment', 2, $j$Assessment 2: Music in Scripture and Worship$j$, $j${"prompt": "Write a report of at least 250 words on music in Scripture and worship. Use complete sentences and label each part. Colossians 3:16 says, Let the word of Christ dwell in you richly in all wisdom; teaching and admonishing one another in psalms and hymns and spiritual songs, singing with grace in your hearts to the Lord.\n\nPart 1: Describe three examples of music in the Old Testament, with Scripture references.\nPart 2: Explain what the Book of Psalms is, what parallelism is, and why we sing with understanding.\nPart 3: Describe three examples of singing in the New Testament and what Ephesians 5:19 and Colossians 3:16 teach.\nPart 4: List four purposes of church singing and five marks of good worship music.\nPart 5: Write a short reflection on how your own singing or listening can be more sincere, orderly and understanding. Choose one psalm, read it aloud slowly and describe what you noticed.", "rubric": "100 points. Part 1: 20 points. Part 2: 20 points. Part 3: 20 points. Part 4: 20 points. Part 5: 15 points. Complete sentences and conventions: 5 points. A score of 70 or above is passing."}$j$::jsonb where not exists (select 1 from public.course_items where course_id = cid and kind = 'assessment' and title = $j$Assessment 2: Music in Scripture and Worship$j$);
  insert into public.course_items (course_id, kind, position, title, content) select cid, 'discussion', 2, $j$Discussion 2: Singing to the LORD$j$, $j${"prompt": "Write a post of at least 120 words that (1) tells which song or hymn has helped your faith most and why, (2) explains what it means to sing with understanding, (3) describes how a church can disagree kindly about music style and still stay united, and (4) connects your answer to First Corinthians 14:15, which says, I will sing with the spirit, and I will sing with the understanding also. Then write a respectful reply of at least 40 words to another student's post, or answer this question: Why do you think Paul and Silas sang in prison instead of complaining? Keep your tone kind and respectful of other views."}$j$::jsonb where not exists (select 1 from public.course_items where course_id = cid and kind = 'discussion' and title = $j$Discussion 2: Singing to the LORD$j$);
  insert into public.course_items (course_id, kind, position, title, content) select cid, 'quiz', 6, $j$Check 2.1: Music in the Old Testament$j$, $j${"questions": [{"q": "After the Red Sea, Moses and Israel:", "options": ["Sang a song to the LORD", "Stopped traveling", "Wrote a hymnbook", "Built a temple"]}, {"q": "Who played the harp to refresh King Saul?", "options": ["Solomon", "Jubal", "Miriam", "David"]}, {"q": "How many trained Levite musicians does First Chronicles 25:7 number?", "options": ["70", "1,000", "12", "288"]}, {"q": "Second Chronicles 5:13 says the trumpeters and singers were:", "options": ["As one, making one sound", "Divided", "Out of tune", "Silent"]}]}$j$::jsonb where not exists (select 1 from public.course_items where course_id = cid and kind = 'quiz' and title = $j$Check 2.1: Music in the Old Testament$j$);
  insert into public.quiz_keys (item_id, answers, explains) select id, '{0,3,3,0}'::int[], array[$j$Exodus 15 records the song of Moses.$j$,$j$First Samuel 16:23 says David took an harp and played.$j$,$j$The verse says two hundred fourscore and eight.$j$,$j$Unity in praise is the picture.$j$] from public.course_items where course_id = cid and kind = 'quiz' and title = $j$Check 2.1: Music in the Old Testament$j$ on conflict (item_id) do nothing;
  insert into public.course_items (course_id, kind, position, title, content) select cid, 'quiz', 7, $j$Check 2.2: The Psalms as Songs$j$, $j${"questions": [{"q": "The Book of Psalms contains how many psalms?", "options": ["27", "150", "66", "39"]}, {"q": "A feature in which the second line repeats, contrasts or builds on the first is called:", "options": ["Parallelism", "Timbre", "Crescendo", "Texture"]}, {"q": "Psalm 47:7 says to sing praises:", "options": ["Only at night", "Without thinking", "With understanding", "Only in secret"]}, {"q": "Psalm 150 calls everything that has breath to:", "options": ["Build a wall", "Praise the LORD", "Be silent", "Travel"]}]}$j$::jsonb where not exists (select 1 from public.course_items where course_id = cid and kind = 'quiz' and title = $j$Check 2.2: The Psalms as Songs$j$);
  insert into public.quiz_keys (item_id, answers, explains) select id, '{1,0,2,1}'::int[], array[$j$There are 150 psalms.$j$,$j$Parallelism is common in Hebrew poetry.$j$,$j$We should think about what we sing.$j$,$j$Psalm 150:6 closes the book with praise.$j$] from public.course_items where course_id = cid and kind = 'quiz' and title = $j$Check 2.2: The Psalms as Songs$j$ on conflict (item_id) do nothing;
  insert into public.course_items (course_id, kind, position, title, content) select cid, 'quiz', 8, $j$Check 2.3: Music in the New Testament and the Early Church$j$, $j${"questions": [{"q": "Where were Paul and Silas when they sang praises at midnight?", "options": ["At the temple", "In a field", "In prison in Philippi", "On a ship"]}, {"q": "Ephesians 5:19 mentions psalms, hymns and:", "options": ["Bells", "Silent prayers", "Spiritual songs", "Drums only"]}, {"q": "First Corinthians 14:40 says all things should be done:", "options": ["Loudly", "Quickly", "Silently", "Decently and in order"]}, {"q": "At the Last Supper, Jesus and His disciples:", "options": ["Left in silence", "Played trumpets", "Sang an hymn", "Danced"]}]}$j$::jsonb where not exists (select 1 from public.course_items where course_id = cid and kind = 'quiz' and title = $j$Check 2.3: Music in the New Testament and the Early Church$j$);
  insert into public.quiz_keys (item_id, answers, explains) select id, '{2,2,3,2}'::int[], array[$j$Acts 16:25 places them in prison in Philippi.$j$,$j$Paul lists three kinds of song.$j$,$j$Order helps everyone be built up.$j$,$j$Matthew 26:30 says they sung an hymn.$j$] from public.course_items where course_id = cid and kind = 'quiz' and title = $j$Check 2.3: Music in the New Testament and the Early Church$j$ on conflict (item_id) do nothing;
  insert into public.course_items (course_id, kind, position, title, content) select cid, 'quiz', 9, $j$Check 2.4: The Purpose of Worship Music$j$, $j${"questions": [{"q": "A cappella singing is:", "options": ["A type of rest", "Voices without instruments", "Only a drum solo", "A very loud style"]}, {"q": "According to John 4:24, true worshippers worship God in:", "options": ["Spirit and in truth", "Fear only", "Silence only", "Loud noise only"]}, {"q": "Colossians 3:16 says singing can:", "options": ["Replace prayer", "Teach and admonish one another", "Be a performance", "Be done only by experts"]}, {"q": "Good worship music should be centered on:", "options": ["God", "The style alone", "The volume", "The performer"]}]}$j$::jsonb where not exists (select 1 from public.course_items where course_id = cid and kind = 'quiz' and title = $j$Check 2.4: The Purpose of Worship Music$j$);
  insert into public.quiz_keys (item_id, answers, explains) select id, '{1,0,1,0}'::int[], array[$j$A cappella means voices alone.$j$,$j$Jesus said God seeks worshippers in spirit and in truth.$j$,$j$Singing teaches and corrects as well as praises.$j$,$j$Worship is directed to God.$j$] from public.course_items where course_id = cid and kind = 'quiz' and title = $j$Check 2.4: The Purpose of Worship Music$j$ on conflict (item_id) do nothing;
  insert into public.course_items (course_id, kind, position, title, content) select cid, 'quiz', 10, $j$Unit Quiz 2: Music in Scripture and Worship$j$, $j${"questions": [{"q": "Who led the women with a timbrel after the Red Sea?", "options": ["Ruth", "Deborah", "Miriam", "Mary"]}, {"q": "David played the harp to refresh:", "options": ["Saul", "Pharaoh", "Solomon", "Moses"]}, {"q": "The Book of Psalms is Israel's:", "options": ["Law code", "Calendar", "Songbook", "Map"]}, {"q": "Selah may mark:", "options": ["A singer's name", "A pause or interlude, though scholars are not certain", "The end of the Bible", "A loud note"]}, {"q": "Mary's song of praise is found in:", "options": ["Psalm 1", "Acts 1", "Luke 1", "Genesis 1"]}, {"q": "Paul and Silas sang praises:", "options": ["At sea", "At midnight in prison", "In the temple", "At a wedding"]}, {"q": "Ephesians 5:19 says to make melody:", "options": ["In your heart to the Lord", "Only with an organ", "Only in secret", "Only on Sundays"]}, {"q": "Good worship music is:", "options": ["Always the loudest", "True to Scripture, understandable and sincere", "Only for experts", "Always from one century"]}]}$j$::jsonb where not exists (select 1 from public.course_items where course_id = cid and kind = 'quiz' and title = $j$Unit Quiz 2: Music in Scripture and Worship$j$);
  insert into public.quiz_keys (item_id, answers, explains) select id, '{2,0,2,1,2,1,0,1}'::int[], array[$j$Exodus 15:20 names Miriam the prophetess.$j$,$j$First Samuel 16:23 tells the story.$j$,$j$The psalms were songs and prayers.$j$,$j$The exact meaning is uncertain, so we say so.$j$,$j$Luke 1:46 and 47 records the Magnificat.$j$,$j$Acts 16:25 gives the scene.$j$,$j$Singing is of the heart.$j$,$j$Truth, understanding and sincerity are marks of good worship.$j$] from public.course_items where course_id = cid and kind = 'quiz' and title = $j$Unit Quiz 2: Music in Scripture and Worship$j$ on conflict (item_id) do nothing;
